INSERT INTO `industri_pilar` (`industri_id`,`pilar_id`,`heading`,`konten`,`fitur`,`urutan`) VALUES
((SELECT id FROM industri WHERE slug='financial'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Always-On Digital Infrastructure for FSI and E-Commerce','<p>Build a resilient, secure digital foundation ready to grow alongside your business needs through High-Availability Data Center and Hybrid Cloud Architecture solutions specifically designed for the Financial Services Industry (FSI) and e-commerce.</p><p>This solution delivers a scalable, secure, resilient, and compliant infrastructure that aligns with regulatory requirements, such as OJK and Bank Indonesia. Consequently, businesses can run critical digital services with optimal availability, performance, and security.</p><p>With an architecture designed to support large-scale financial transactions and digital commerce, enterprises can process millions of transactions in real-time with low latency, stable performance, and flexible capacity that adapts to traffic growth and business volume.</p><p>We help ensure service continuity through a multi-tiered infrastructure design, failover mechanisms, disaster recovery, proactive monitoring, and structured operational management to minimize downtime risks and keep services running under various business conditions.</p><p>Supported by always-on digital infrastructure, your business can deliver fast, stable, secure, and trusted user experiences—ranging from banking transactions, digital payments, and marketplaces to loyalty platforms and enterprise-scale commerce services.</p>','[{"icon": "", "judul": "High-Availability Data Center", "teks": ""}, {"icon": "", "judul": "Hybrid Cloud Architecture", "teks": ""}, {"icon": "", "judul": "Scalable, Secure & Resilient", "teks": ""}, {"icon": "", "judul": "Regulatory Compliance (OJK & BI)", "teks": ""}]',1),
((SELECT id FROM industri WHERE slug='financial'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Deploy AI Avatars Ready to Serve, Sell, and Engage 24/7','<p>Elevate customer and client experience with Generative AI Avatar solutions capable of interacting naturally, personally, and in real time. By combining Large Language Models (LLM), data management, and intelligent automation, this solution helps businesses deliver faster, more consistent, and relevant digital services at every interaction touchpoint.</p><p>On the physical security side, this solution is reinforced with AI Surveillance Cameras capable of proactively monitoring banking areas, branch offices, ATMs, warehouses, and critical operational zones. This intelligent surveillance technology helps detect suspicious activity, behavioral patterns, potential unauthorized access, and security incidents in real time, enabling faster risk identification and response.</p><p>For the Financial Services Industry: AI Avatars act as virtual consultants that explain products, address client inquiries, and improve service quality without operational hour constraints.</p><p>For the E-Commerce Industry: AI Avatars serve as Live Commerce hosts that conduct autonomous live streams, promote products, answer customer inquiries in chat, provide recommendations, and drive real-time transactions.</p><p>With this solution, enterprises can boost engagement, accelerate service delivery, gain accurate business insights, and drive sales conversion and customer loyalty through interactive digital experiences.</p>','[{"icon": "", "judul": "Generative AI Avatar", "teks": ""}, {"icon": "", "judul": "Large Language Models (LLM)", "teks": ""}, {"icon": "", "judul": "Intelligent Automation", "teks": ""}, {"icon": "", "judul": "AI Surveillance Cameras", "teks": ""}, {"icon": "", "judul": "Virtual Consultant (FSI)", "teks": ""}, {"icon": "", "judul": "Live Commerce Host", "teks": ""}]',2),
((SELECT id FROM industri WHERE slug='financial'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Multi-Layered Cybersecurity to Protect Your Transactions, Data, and Brand Reputation','<p>In the FSI and e-commerce sectors, every second of downtime, data breach, cyberattack, or brand misuse directly impacts revenue, regulatory compliance, and customer trust. Therefore, we provide an integrated cybersecurity solution that unites detection, protection, monitoring, threat intelligence, and automated response within a comprehensive security ecosystem.</p><p>Powered by EDR, NDR, XDR, Next-Generation Firewalls, WAF, centralized SIEM, and AI-driven SOAR, your enterprise can detect threats faster, respond to incidents with greater precision, and mitigate disruption risks to core digital services.</p><p>We also offer proactive Threat Intelligence to monitor potential data leaks, phishing attempts, fraud, brand identity infringement, hoax content, and the unauthorized exposure of sensitive data across the internet and social media. Should risks to your business be identified, we assist with escalation and take-down processes to minimize the impact on public trust and corporate reputation.</p><p>This solution is engineered to help organizations sustain transaction security, data protection, regulatory compliance, operational stability, and long-term digital business resilience.</p>','[{"icon": "", "judul": "EDR", "teks": ""}, {"icon": "", "judul": "NDR", "teks": ""}, {"icon": "", "judul": "XDR", "teks": ""}, {"icon": "", "judul": "Next-Generation Firewall", "teks": ""}, {"icon": "", "judul": "WAF", "teks": ""}, {"icon": "", "judul": "SIEM", "teks": ""}, {"icon": "", "judul": "SOAR", "teks": ""}, {"icon": "", "judul": "Threat Intelligence", "teks": ""}]',3),
((SELECT id FROM industri WHERE slug='financial'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'IT & Cybersecurity Managed Services for Mission-Critical Businesses','<p>Ensure your digital operations remain secure, stable, and prepared for emerging threats with STT Managed Services. Beyond proactive 24/7/365 infrastructure and security monitoring, we strengthen system resilience through advanced services such as Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, Cyber Drills, and Table Top Exercises.</p><p>Supported by routine patch management, comprehensive IT operational governance, and rapid responses to potential disruptions and cyberattacks, your enterprise can maintain high performance, continuous security, and uninterrupted service across every digital transaction.</p><p>The Result: A more resilient system, better-controlled risks, internal teams focused on core business functions, and seamless, secure, fast experiences for your end customers.</p>','[{"icon": "", "judul": "24/7/365 Monitoring", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Cyber Drills", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}, {"icon": "", "judul": "Patch Management", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='manufacture'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Accelerate Production, Connect All Sites, and Drive Decisions with Real-Time Data','<p>In the manufacturing and FMCG sectors, data delays, connectivity disruptions, and lack of cross-site visibility directly impair productivity, production quality, and distribution speed. Consequently, we provide modern IT infrastructure solutions powered by Edge Computing and SD-WAN to build faster, stable, secure, and integrated operations.</p><p>Edge Computing enables data from production machinery, sensors, quality control systems, and plant applications to be processed in real time directly at the operational site without relying entirely on a central data center connection. As a result, enterprises can respond to shop-floor conditions faster, reduce latency, and support high-precision process automation.</p><p>SD-WAN seamlessly, efficiently, and securely interconnects headquarters, manufacturing plants, logistics warehouses, and distribution points. Cross-site data communication becomes more stable, supporting end-to-end coordination across production, inventory, supply chain, distribution, and operational monitoring.</p><p>With enhanced data visibility and reliable connectivity, enterprises can boost production efficiency, accelerate decision-making, mitigate downtime risks, and build an operational chain that adapts fluidly to shifting market demands.</p>','[{"icon": "", "judul": "Edge Computing", "teks": ""}, {"icon": "", "judul": "SD-WAN", "teks": ""}, {"icon": "", "judul": "Real-Time Shop-Floor Processing", "teks": ""}, {"icon": "", "judul": "Multi-Site Connectivity", "teks": ""}]',1),
((SELECT id FROM industri WHERE slug='manufacture'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Reduce Defects, Enhance Safety, and Secure Production Areas with Computer Vision','<p>In manufacturing and FMCG, product quality, workplace safety, and production area security should not depend solely on manual oversight. An intelligent system capable of real-time monitoring, detection, and insight generation is required to ensure operations run with precision, safety, and consistency.</p><p>We deliver Computer Vision solutions to automate quality control, detect production defects, and maintain product standards across every process. The system identifies anomalies in products, packaging, labeling, dimensions, colors, and other visual parameters to support faster, more accurate quality control.</p><p>In terms of workplace safety, AI Surveillance Cameras monitor compliance with Personal Protective Equipment (PPE) standards in real time, helping companies enforce occupational health and safety (OHS/K3) standards and reduce workplace accident risks.</p><p>For high-security zones, Computer Vision Smart Access regulates access to production floors, warehouses, laboratories, and restricted areas, ensuring only authorized personnel can enter.</p><p>Through these capabilities, companies can improve quality consistency, accelerate inspection workflows, strengthen safety cultures, and protect operational security across production and logistics facilities.</p>','[{"icon": "", "judul": "Computer Vision Quality Control", "teks": ""}, {"icon": "", "judul": "Defect Detection", "teks": ""}, {"icon": "", "judul": "AI Surveillance (PPE/Safety)", "teks": ""}, {"icon": "", "judul": "Computer Vision Smart Access", "teks": ""}]',2),
((SELECT id FROM industri WHERE slug='manufacture'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Integrated Cybersecurity to Protect IT, OT/IoT, and Manufacturing Operations','<p>Protect your manufacturing and FMCG ecosystem with a holistic cybersecurity solution that unifies Information Technology (IT), Operational Technology (OT), and Internet of Things (IoT) defense into an integrated framework. This solution safeguards plant operational continuity, protects production data, and mitigates cyberattack risks that could disrupt supply chains, production lines, and brand integrity.</p><p>We deliver multi-layered defense using EDR, NDR, XDR, Next-Generation Firewalls, WAF, centralized SIEM, and AI-driven SOAR to provide complete visibility across endpoints, networks, applications, servers, and plant floor environments. Featuring precise threat detection and automated incident response, organizations can identify risks faster, accelerate containment, and minimize operational impacts.</p><p>This solution is supported by Threat Intelligence that proactively monitors for unauthorized exposures of confidential company data—including product formulas, production documents, R&D data, credentials, supply chain details, and other sensitive information across the internet, dark web, and social channels. Furthermore, we detect phishing threats, brand impersonation, and vendor/supplier ecosystem attack vectors.</p><p>When risks that threaten business continuity are detected, we provide dedicated escalation and take-down support to curb data exposure, protect intellectual property, preserve production data integrity, and maintain partner and customer trust.</p><p>Through an integrated, proactive, and uptime-oriented security approach, manufacturing and FMCG enterprises can maintain secure, stable, and resilient production processes shielded from modern cyber threats.</p>','[{"icon": "", "judul": "IT/OT/IoT Security", "teks": ""}, {"icon": "", "judul": "EDR", "teks": ""}, {"icon": "", "judul": "NDR", "teks": ""}, {"icon": "", "judul": "XDR", "teks": ""}, {"icon": "", "judul": "Next-Generation Firewall", "teks": ""}, {"icon": "", "judul": "WAF", "teks": ""}, {"icon": "", "judul": "SIEM", "teks": ""}, {"icon": "", "judul": "SOAR", "teks": ""}, {"icon": "", "judul": "Threat Intelligence", "teks": ""}]',3),
((SELECT id FROM industri WHERE slug='manufacture'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'Managed Services for Stable, Secure, and Always-On Manufacturing Operations','<p>Maintain continuous manufacturing and FMCG operations through 24/7 Managed Services designed to preserve the stability of IT infrastructure, plant networks, production systems, and digital supply chain ecosystems.</p><p>We provide proactive, remote network device monitoring across facilities to detect potential anomalies early, accelerate incident handling, and maintain stable connectivity between production plants, warehouses, head offices, and operational sites.</p><p>This service covers end-to-end IT operational management—ranging from system performance monitoring, data storage capacity management, and infrastructure maintenance to backup and disaster recovery. This ensures high data availability and operational business continuity during system failures, outages, or unforeseen incidents.</p><p>To reinforce cybersecurity posture, we offer Managed Security Services encompassing Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, Cyber Drills, and Table Top Exercises. This approach enables enterprises to identify vulnerabilities, analyze incident impacts, test response readiness, and continuously mitigate cyber risks.</p><p>With integrated Managed Services support, manufacturing firms can sustain production stability, enhance operational efficiency, protect critical data, and minimize disruption risks across the entire value chain.</p>','[{"icon": "", "judul": "24/7 Network Monitoring", "teks": ""}, {"icon": "", "judul": "Backup & Disaster Recovery", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Cyber Drills", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='healthcare'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Digital Healthcare Infrastructure for Fast, Secure, and Always-Available Medical Services','<p>Build a reliable, secure, and future-ready hospital IT foundation to support modern healthcare services that rely heavily on data, high-speed connectivity, and rapid access to clinical information.</p><p>Our solution delivers high-capacity, high-performance medical data storage systems designed for medical imaging, radiology, and Picture Archiving and Communication System (PACS) environments. Featuring fast and stable data access performance, medical staff can view, archive, and analyze diagnostic imaging results with greater efficiency and precision.</p><p>Supported by a stable, redundant, and always-on hospital network, critical applications such as Electronic Medical Records (EMR), e-prescribing, hospital administration systems, laboratory information systems, pharmacy systems, and digital clinical services run without interruption.</p><p>Featuring scalable, secure, and high-availability architectures, hospitals can accelerate service delivery, preserve patient data availability, strengthen operational continuity, and provide faster, more accurate, and trusted healthcare experiences.</p>','[{"icon": "", "judul": "Medical Data Storage (PACS)", "teks": ""}, {"icon": "", "judul": "Redundant Hospital Network", "teks": ""}, {"icon": "", "judul": "EMR & Clinical Systems", "teks": ""}, {"icon": "", "judul": "High Availability & Scalability", "teks": ""}]',1),
((SELECT id FROM industri WHERE slug='healthcare'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Accelerate Diagnosis, Optimize Clinical Workflows, and Deliver Smarter Patient Experiences','<p>In modern healthcare, instant data access, precise medical analytics, and integrated patient journeys are crucial factors in elevating care quality. We provide Data & AI solutions for Healthcare that help hospitals and medical institutions optimize clinical workflows from initial consultation to post-care management.</p><p>Radiology & Pathology Computer Vision: AI enhances medical imaging quality—including MRI image enhancement (1.5T → 3T optimization)—and supports CT scan and digital pathology analyses. This solution accelerates diagnostic workflows, increases reading consistency, and assists clinicians in making data-driven decisions.</p><p>Smart Patient Assist: Delivers structured, personalized patient experiences. An intelligent triage system identifies patient needs early, recommends appropriate specialists, and automates appointment scheduling. During consultations, AI supports real-time medical data analysis and patient summaries. Post-consultation, the system automates follow-ups, medication reminders, control appointments, and continuous communication.</p><p>Through an end-to-end approach, healthcare institutions can boost operational efficiency, accelerate service delivery, ensure clinical accuracy, and create comfortable, personalized, and sustainable patient experiences.</p>','[{"icon": "", "judul": "Radiology & Pathology Computer Vision", "teks": ""}, {"icon": "", "judul": "MRI Image Enhancement", "teks": ""}, {"icon": "", "judul": "Smart Patient Assist", "teks": ""}, {"icon": "", "judul": "Intelligent Triage", "teks": ""}]',2),
((SELECT id FROM industri WHERE slug='healthcare'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Protect Patient Data, Hospital Systems, and Medical Devices from Cyber Threats','<p>In healthcare, a cyberattack is not merely an IT outage. Ransomware, patient data breaches, unauthorized access, or Medical IoT/IoMT compromises can halt clinical operations, disrupt hospital functions, and erode patient trust.</p><p>We deliver an integrated cybersecurity solution that protects the entire healthcare ecosystem—spanning IT infrastructure, clinical applications, hospital networks, and connected medical devices. Combining EDR, NDR, XDR, Next-Generation Firewalls, WAF, centralized SIEM, AI-driven SOAR, and Threat Intelligence, hospitals gain expanded visibility, precise threat detection, and coordinated incident response.</p><p>Through proactive Threat Intelligence, we monitor for potential patient data leaks, ransomware threats, credential theft, sensitive data exposure, and brand abuse across open-web and social channels. If risks threatening patient privacy or institutional reputation are detected, we support escalation and content take-downs to mitigate impact.</p><p>By unifying IT and Medical IoT/IoMT security, healthcare institutions can enforce data privacy, protect medical system integrity, ensure uninterrupted clinical care, and strengthen public trust.</p>','[{"icon": "", "judul": "Medical IoT/IoMT Security", "teks": ""}, {"icon": "", "judul": "EDR", "teks": ""}, {"icon": "", "judul": "NDR", "teks": ""}, {"icon": "", "judul": "XDR", "teks": ""}, {"icon": "", "judul": "Next-Generation Firewall", "teks": ""}, {"icon": "", "judul": "WAF", "teks": ""}, {"icon": "", "judul": "SIEM", "teks": ""}, {"icon": "", "judul": "SOAR", "teks": ""}, {"icon": "", "judul": "Threat Intelligence", "teks": ""}]',3),
((SELECT id FROM industri WHERE slug='healthcare'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'Managed Services for Stable, Secure, and Always-Ready Hospital Operations','<p>Ensure hospital and healthcare operations function at peak performance with 24/7 Managed Services designed to maintain the availability, performance, and security of IT infrastructure and critical patient care systems.</p><p>We provide proactive, remote monitoring of hospital IT infrastructure, networks, servers, medical data storage, clinical software, and core platforms such as EMR, PACS, e-prescribing, laboratory, pharmacy, and patient management systems. Continuous monitoring allows potential issues to be identified and remediated early before clinical operations are impacted.</p><p>This service delivers end-to-end IT operational support—including medical storage capacity management, system performance maintenance, routine backups, and disaster recovery—guaranteeing that vital patient data remains available and care services can be restored rapidly during emergency events or outages.</p><p>To strengthen defense postures, our Managed Security Services offer Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, Cyber Drills, and Table Top Exercises. This structured strategy helps healthcare providers discover vulnerabilities, analyze security events, test response readiness, and mitigate cyber risks targeting sensitive patient records and medical networks.</p><p>With integrated Managed Services, medical institutions sustain operational stability, protect patient privacy, lighten internal IT workloads, and ensure care services remain secure, efficient, and uninterrupted.</p>','[{"icon": "", "judul": "24/7 Clinical Systems Monitoring", "teks": ""}, {"icon": "", "judul": "Medical Storage Management", "teks": ""}, {"icon": "", "judul": "Backup & Disaster Recovery", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Cyber Drills", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='telecom'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Hyperscale Data Center Infrastructure for Scalable Telecom and ICT Ecosystems','<p>Build a large-scale digital foundation to support the growth of the telecommunications and ICT industries through Hyperscale Data Center infrastructure engineered for high availability, optimal performance, multi-layered security, and effortless scalability as traffic, data, and digital services expand.</p><p>This solution leverages Edge Computing to fulfill modern network needs, including 5G rollouts, low-latency applications, IoT deployments, video streaming, enterprise offerings, and large-scale digital platforms. Processing data closer to end-users and service points reduces latency, speeds up response times, and yields stable, consistent digital experiences.</p><p>Through Software-Defined Networking (SDN) and SD-WAN implementations, network management becomes central, agile, and efficient. Infrastructure can be rapidly configured, optimized, and scaled to handle core network operations, data center interconnects, enterprise links, and regional service expansions.</p><p>Backboned by Hybrid Cloud, High Availability, and Disaster Recovery architectures, this solution preserves critical service availability, protects high-value applications and data, and speeds up operational recovery after unexpected disruptions. Featuring a resilient, secure framework, telecom operators and ICT providers can elevate service performance, drive operational efficiency, and build a digital ecosystem ready for future growth.</p>','[{"icon": "", "judul": "Hyperscale Data Center", "teks": ""}, {"icon": "", "judul": "Edge Computing (5G)", "teks": ""}, {"icon": "", "judul": "Software-Defined Networking (SDN)", "teks": ""}, {"icon": "", "judul": "SD-WAN", "teks": ""}, {"icon": "", "judul": "Hybrid Cloud", "teks": ""}, {"icon": "", "judul": "High Availability & DR", "teks": ""}]',1),
((SELECT id FROM industri WHERE slug='telecom'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'GenAI Avatars for Personalized, Responsive, and Always-Active Telecom Customer Service','<p>Elevate digital customer engagement through GenAI Avatar solutions powered by Large Language Models (LLM) that deliver natural, personalized, and responsive interactions across all telecom service channels.</p><p>This solution enables 24/7 automated resolution for customer inquiries and requests, including service plan info, bill checking, connectivity troubleshooting, service activations, self-service app navigation, and tailored product recommendations based on user profiles.</p><p>With the ability to comprehend conversational context and respond with speed, consistency, and empathy, GenAI Avatars accelerate resolution times while alleviating contact center workloads. Customers receive instant support without standing in manual service queues.</p><p>Fully integrated with operational databases and core systems, this solution drives accurate, personalized, and measurable service workflows. Customer interactions are converted into actionable analytics to better understand subscriber needs, elevate service quality, and refine digital experiences.</p><p>With GenAI Avatars, telecom companies can improve customer satisfaction, build subscriber loyalty, optimize operational overhead, and deliver modern, agile, competitive digital services.</p>','[{"icon": "", "judul": "GenAI Avatar", "teks": ""}, {"icon": "", "judul": "Large Language Models (LLM)", "teks": ""}, {"icon": "", "judul": "24/7 Automated Resolution", "teks": ""}, {"icon": "", "judul": "Customer Interaction Analytics", "teks": ""}, {"icon": "", "judul": "Core System Integration", "teks": ""}]',2),
((SELECT id FROM industri WHERE slug='telecom'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Protect 4G/5G Networks against DDoS, Fraud, and Large-Scale Cyber Threats','<p>In telecommunications, network downtime extends far beyond a technical inconvenience. DDoS attacks, digital fraud, account takeovers, and system breaches immediately damage service quality, subscriber trust, and operator brand equity.</p><p>We offer integrated cybersecurity solutions that safeguard telecom networks, digital services, subscriber databases, and critical infrastructure against advanced threats. Utilizing DDoS Protection, EDR, NDR, XDR, centralized SIEM, AI-driven SOAR, and Threat Intelligence, operators gain comprehensive visibility, pinpoint threat detection, and synchronized incident response capabilities.</p><p>Robust DDoS Protection defends 4G/5G service availability, customer portals, mobile applications, and backend systems against malicious traffic surges. Meanwhile, SIEM and SOAR work in tandem to accelerate event correlation, automate countermeasures, and reduce mean time to respond (MTTR).</p><p>Through proactive Threat Intelligence, operators can track anomalous activities, account compromise attempts, phishing campaigns, credential theft, and digital fraud schemes that endanger both customers and revenues. Through multi-tiered defense, telecom providers preserve network stability, secure subscriber data, and offer trusted, resilient connectivity services.</p>','[{"icon": "", "judul": "DDoS Protection", "teks": ""}, {"icon": "", "judul": "EDR", "teks": ""}, {"icon": "", "judul": "NDR", "teks": ""}, {"icon": "", "judul": "XDR", "teks": ""}, {"icon": "", "judul": "SIEM", "teks": ""}, {"icon": "", "judul": "SOAR", "teks": ""}, {"icon": "", "judul": "Threat Intelligence", "teks": ""}]',3),
((SELECT id FROM industri WHERE slug='telecom'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'Managed Services for Stable, Efficient Telecom Networks Built for Traffic Spikes','<p>Drive telecommunication operations with Managed Services designed for continuous stability, performance, and high availability. This solution empowers operators and ICT service providers to proactively, efficiently, and securely manage critical infrastructure.</p><p>We deliver operational management and monitoring for servers, storage, networks, service platforms, and telecom infrastructure that form the backbone of customer connectivity. Continuous surveillance ensures potential faults are detected and resolved before impacting service delivery quality.</p><p>Services include proactive server and storage capacity optimization to handle traffic surges, subscriber growth, digital service expansion, and exploding data volumes. Planned capacity management ensures optimal performance without wasteful resource over-provisioning.</p><p>To reinforce overall security posture, we provide advanced offerings such as Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, Table Top Exercises, and Cyber Drills. This methodology identifies technical security gaps, analyzes incident vectors, tests readiness, and mitigates risks facing telecom assets.</p><p>Through integrated Managed Services, telecom operators can improve operational efficiency, secure network stability, accelerate issue resolution, and provide reliable, uniform customer experiences.</p>','[{"icon": "", "judul": "24/7 Infrastructure Monitoring", "teks": ""}, {"icon": "", "judul": "Capacity Optimization", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}, {"icon": "", "judul": "Cyber Drills", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='law-enforcement'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Reliable Infrastructure for Mission-Critical Operations','<p>Technology systems within law enforcement represent mission-critical operations. Operational software, databases, command centers, investigative platforms, video surveillance streams, and digital evidence demand continuous infrastructure availability whenever needed.</p><p>Sapta Tunas Teknologi builds infrastructure architectures that prioritize availability, scalability, performance, connectivity, and business continuity.</p>','[{"icon": "", "judul": "Secure, High-Availability Data Centers", "teks": "<p>Data centers serve as the operational nexus for all software applications and intelligence databases. The underlying infrastructure must handle growing data volumes while keeping mission-critical services operational during hardware failures.</p><p>Sapta Tunas Teknologi designs compute, server, enterprise storage, network, and data protection architectures using high-availability principles—eliminating single points of failure for essential workloads.</p><p>This framework supports diverse operational demands—including command centers, field applications, case databases, video management systems (VMS), analytics engines, and digital evidence repositories.</p>"}, {"icon": "", "judul": "Virtualization & Private Cloud", "teks": "<p>Not all law enforcement workloads can reside on public cloud platforms. Data sovereignty, security requirements, regulatory compliance, and performance demands make private infrastructure a strategic imperative.</p><p>Virtualization and Private Cloud solutions unify server, storage, and networking resources into a flexible pool—accelerating workload provisioning, maximizing resource utilization, and decreasing reliance on isolated physical servers per application.</p>"}, {"icon": "", "judul": "Reliable Networking & Connectivity", "teks": "<p>Law enforcement agencies operate across dispersed geographic locations—ranging from headquarters and regional offices to command centers and mobile field units. Every node demands stable, secure connectivity to ensure information remains accessible.</p><p>Sapta Tunas Teknologi builds enterprise networks that interconnect facilities, data centers, and operational tools within a unified environment. Centralized security and monitoring provide complete visibility over infrastructure health and network traffic.</p>"}, {"icon": "", "judul": "Edge Computing for Field Operations", "teks": "<p>Not all field data must travel to a central data center prior to processing. For edge-based requirements such as local video analytics and large-scale data processing, Edge Computing executes tasks close to the data source.</p><p>This design reduces network latency, optimizes bandwidth consumption, and maintains processing continuity even under constrained central connectivity. Edge nodes remain linked with central data centers for consolidation, advanced analytics, and governance.</p>"}, {"icon": "", "judul": "Backup & Disaster Recovery", "teks": "<p>Operational records and digital evidence carry immense value—their loss or unavailability can compromise active investigations and public safety. Consequently, basic backups are insufficient.</p><p>Sapta Tunas Teknologi designs Backup, Data Protection, Disaster Recovery, and Cyber Recovery frameworks to ensure applications and critical records possess reliable recovery paths against hardware failures, human error, natural disasters, or ransomware attacks.</p>"}]',1),
((SELECT id FROM industri WHERE slug='law-enforcement'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Transforming Data into Actionable Intelligence','<p>Law enforcement agencies manage massive volumes of information—incident reports, case files, legal records, video feeds, imagery, and open-source data. The primary challenge lies in uncovering connections, hidden patterns, and key insights quickly.</p><p>Sapta Tunas Teknologi integrates Data Platforms, Analytics engines, Computer Vision, and Artificial Intelligence to convert raw data streams into actionable intelligence.</p>','[{"icon": "", "judul": "Criminal Intelligence & Case Analytics", "teks": "<p>Case information often resides in isolated databases, spreadsheets, and document stores. Advanced data analytics unifies authorized data streams into a cohesive view for investigators and intelligence analysts.</p><p>Analytics platforms highlight hidden relationships, suspect activity patterns, and event timelines that are difficult to discern manually. AI acts as a decision-support tool, while final interpretations and actionable decisions remain strictly with authorized officers according to statutory procedures.</p>"}, {"icon": "", "judul": "Facial Recognition & Video Analytics", "teks": "<p>Thousands of camera feeds in command centers and public areas generate video streams that cannot be reviewed manually.</p><p>Computer Vision converts raw video into searchable data structures—supporting object detection, visual recognition, event detection, and authorized identity verification in alignment with statutory policies.</p><p>Implementation is coupled with data governance, explicit authorization levels, privacy controls, and audit trails to guarantee regulatory compliance.</p>"}, {"icon": "", "judul": "Predictive Analytics & Operational Risk Assessment", "teks": "<p>Historical data can reveal underlying operational patterns. Leveraging statistical analytics and machine learning, agencies can identify trends, heatmaps, and anomalies to inform resource allocation and operational planning.</p><p>Examples include analyzing crime incident patterns over time and space, tracking operational shifts, and assessing risk levels. This capability serves purely as analytical support rather than an automated decision maker regarding individual actions. Thus, AI heightens situational awareness while fully respecting human judgment and due process.</p>"}, {"icon": "", "judul": "Data Lakehouse & Real-Time Dashboards", "teks": "<p>Data silos remain a challenge for large public institutions. Dispersed data across ministry or agency systems prevents leadership from obtaining a quick, consolidated operational picture.</p><p>Sapta Tunas Teknologi resolves this using a Data Lakehouse architecture—a modern enterprise data platform that unifies structured and unstructured systems into a single foundation ready for analytics and AI models.</p><p>Information is rendered via real-time operational dashboards that deliver situational awareness to command centers and executive leadership on demand—displaying indicative and predictive analytics, trend maps, spatial coverage, active incident statuses, and key operational metrics.</p>"}, {"icon": "", "judul": "Document Management & Digital Evidence Analysis", "teks": "<p>Investigations frequently involve processing thousands of case files, images, and electronic logs.</p><p>Utilizing AI and Intelligent Document Processing (IDP), Sapta Tunas Teknologi delivers OCR, document classification, automated metadata extraction, and smart indexing, allowing evidence to be cataloged and searched rapidly.</p><p>Through evidence analytics, investigators locate specific details without manual page-by-page reviews. All information is stored within secure repositories featuring fine-grained access controls, immutable audit logs, and complete chain-of-custody tracking.</p>"}]',2),
((SELECT id FROM industri WHERE slug='law-enforcement'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Safeguarding Critical Systems, Sensitive Records, and Digital Evidence','<p>In the digital era, cybersecurity is foundational to law enforcement operations. Threat vectors arise from multiple origins—external threat actors, malware, compromised accounts, vulnerable applications, and unauthorized internal access.</p><p>Defense strategies must cover users, devices, networks, applications, and sensitive databases.</p>','[{"icon": "", "judul": "Threat Detection & Security Operations Center (SOC)", "teks": "<p>A Security Operations Center (SOC) supplies centralized visibility over institutional cyber defense postures. Event logs across servers, endpoints, firewalls, and network appliances are aggregated and analyzed via SIEM platforms.</p><p>SOC teams monitor potential indicators of compromise around the clock, shifting institutional security from a reactive posture to proactive detection and response.</p>"}, {"icon": "", "judul": "Endpoint Protection", "teks": "<p>Laptops, desktops, servers, and mobile units represent primary attack vectors.</p><p>Endpoint Security alongside EDR/XDR platforms monitor host activities, detect suspicious behavior, and execute automated containment when compromises occur. Centralized endpoint visibility allows security teams to investigate and remediate incidents rapidly.</p>"}, {"icon": "", "judul": "Network Security & Micro-Segmentation", "teks": "<p>Network security prevents unauthorized external access while restricting internal lateral movement if a perimeter is breached.</p><p>Network micro-segmentation isolates systems by operational function and classification level—separating user networks, server infrastructure, management interfaces, video monitoring environments, and digital evidence repositories. Access policies follow strict Least Privilege principles.</p>"}, {"icon": "", "judul": "Secure Access & Identity Governance", "teks": "<p>Identity management forms the backbone of Zero Trust security. Access Management verifies that only authorized personnel reach specific applications and evidentiary records.</p><p>Implementing multi-factor authentication, role-based access control (RBAC), and Privileged Access Management (PAM) mitigates unauthorized access risks. All access attempts generate immutable audit logs for compliance reviews and internal investigations.</p>"}, {"icon": "", "judul": "Data Protection & Encryption", "teks": "<p>Investigative files, personal data, and evidence require protection both at rest and in transit.</p><p>Strong encryption, robust access policies, and secure backup routines uphold data confidentiality and integrity. To preserve operational continuity, data protection is coupled with backup, disaster recovery, and cyber recovery solutions—ensuring clean data copies are available if primary environments fail.</p>"}]',3),
((SELECT id FROM industri WHERE slug='law-enforcement'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'Managed Services for Stable, Secure, and Public-Facing Law Enforcement Operations','<p>In public safety operations, disruptions across networks, citizen reporting portals, case databases, or video archives directly hinder incident response times and public trust. Our Managed Services ensure mission-critical IT infrastructure remains secure, stable, and operational around the clock.</p><p>Our scope includes full lifecycle management of IT assets, high-capacity CCTV storage management, network hardware maintenance across precincts, and proactive monitoring of core operational components. Potential failures are identified and addressed prior to impacting field operations.</p><p>To support public engagement, we guarantee high availability for citizen reporting portals—ensuring reliable access for incident reporting, transparency, and rapid community response.</p><p>Bolstered by advanced security offerings—including VAPT, Digital Forensics, and Table Top Exercises—agencies can elevate system resilience, stress-test response protocols, and neutralize cyber risks directed at sensitive criminal databases and command software.</p><p>This end-to-end management framework ensures operational stability, data integrity, reliable public service delivery, and seamless cross-agency coordination for modern, responsive law enforcement.</p>','[{"icon": "", "judul": "IT Asset Lifecycle Management", "teks": ""}, {"icon": "", "judul": "High-Capacity CCTV Storage", "teks": ""}, {"icon": "", "judul": "Network Hardware Maintenance", "teks": ""}, {"icon": "", "judul": "Citizen Reporting Portal Uptime", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='energy'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Rugged Infrastructure for Mission-Critical Energy Operations','<p>Technology infrastructure across Oil & Gas, Mining, and Utilities must support geographically dispersed environments, complex computing workloads, and high uptime targets. Infrastructure design cannot concentrate solely on central data centers; it must guarantee that systems and data remain performant at remote plants, mines, and offshore sites.</p><p>Sapta Tunas Teknologi assists organizations in architecting scalable, resilient infrastructure environments—spanning compute, enterprise storage, networking, virtualization, private/hybrid clouds, data protection, and disaster recovery, alongside HCI and Non-HCI architectures.</p>','[{"icon": "", "judul": "High-Performance Computing (HPC)", "teks": "<p>Digitization in the energy sector drives computing demands—requiring parallel processing to run complex energy analytics, seismic modeling, reservoir simulations, computer vision, and machine learning models.</p><p>Sapta Tunas Teknologi designs modern data center architectures equipped with scalable servers, enterprise storage arrays, and high-speed fabrics. For resource-intensive AI and analytics workloads, processing power can be expanded using accelerated GPU computing architectures. Infrastructure capacity scales incrementally alongside data volume growth without requiring complete system redesigns.</p>"}, {"icon": "", "judul": "Secure Multi-Site Networking", "teks": "<p>Energy enterprises operate across broad, challenging geographies. Unifying head offices, data centers, processing plants, surface mines, drilling sites, and remote control rooms requires secure, reliable connectivity to exchange real-time operational data.</p><p>At the enterprise level, networks route traffic efficiently between users, business systems, and data centers. Across operational sites, network segmentation isolates IT zones, OT environments, and safety-critical control networks according to risk profiles. Centralized network monitoring provides administrators full visibility over operational links.</p>"}, {"icon": "", "judul": "Hybrid Cloud (Right Workload Placement)", "teks": "<p>Energy applications vary in their infrastructure requirements. While select enterprise applications thrive in public clouds, critical operational applications, sensitive operational data, and latency-sensitive workloads perform best on dedicated private infrastructure.</p><p>Sapta Tunas Teknologi helps companies integrate on-premise infrastructure with cloud environments, enabling workload placement based on performance, data privacy, regulatory compliance, and continuity demands. Our core principle is straightforward: the Right Infrastructure for the Right Workload.</p>"}, {"icon": "", "judul": "IT & OT Converged Infrastructure", "teks": "<p>Connecting the worlds of Information Technology and Operational Technology requires strict architecture controls. Data generated on shop floors can feed enterprise data platforms to power analytics and predictive models; however, direct, unmonitored interconnections expose industrial control systems to external risks.</p><p>Sapta Tunas Teknologi constructs secure bridge architectures that enable controlled IT/OT data exchange utilizing network segmentation, strict access policies, traffic inspection, and industrial security standards. This foundation supports Industrial IoT (IIoT), operational analytics, and predictive maintenance programs without exposing critical Industrial Control Systems (ICS) to cyber vectors.</p>"}, {"icon": "", "judul": "Backup, Disaster Recovery & Cyber Resiliency", "teks": "<p>Lost data or system downtime in energy production can incur severe financial and environmental costs. Consequently, data protection must be embedded directly into corporate business continuity strategies.</p><p>Sapta Tunas Teknologi builds end-to-end architectures incorporating backup, data replication, disaster recovery, and cyber resiliency. Critical workloads are classified by Recovery Time Objectives (RTO) and Recovery Point Objectives (RPO), establishing tailored recovery paths aligned with operational criticality.</p>"}]',1),
((SELECT id FROM industri WHERE slug='energy'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Transforming Operational Data into Actionable Intelligence','<p>Energy companies generate massive volumes of data—originating from SCADA systems, IoT sensors, heavy machinery, video cameras, inspection logs, engineering platforms, and satellite feeds. The real value of this data is unlocked when it is converted into actionable insights that increase operational reliability, safety, and efficiency.</p><p>Sapta Tunas Teknologi provides an integrated portfolio spanning Data Management, Data Analytics, Data Lakehouses, AI Platforms, Computer Vision, and Agentic AI to power enterprise analytics initiatives.</p>','[{"icon": "", "judul": "Predictive Maintenance & Asset Intelligence", "teks": "<p>Traditional maintenance operates on fixed schedules or reactively following equipment failure. By aggregating historical sensor data and operational telemetry, companies can transition toward condition-based and predictive maintenance models.</p><p>Operating conditions, historical performance data, event logs, and maintenance records consolidate into unified data platforms for automated analysis. Machine learning algorithms detect subtle equipment degradation patterns, offering maintenance teams early warning indicators—reducing unplanned downtime, increasing asset utilization, and extending the lifecycle of critical machinery.</p>"}, {"icon": "", "judul": "Production & Operational Analytics", "teks": "<p>Operational data often remains trapped within functional silos, forcing teams to manually compile reports across disparate systems to evaluate plant health.</p><p>Modern Data Platforms consolidate operational and enterprise data into a unified analytics environment. Custom dashboards display real-time production performance, asset utilization, key performance indicators (KPIs), downtime tracking, and energy consumption metrics. For Oil & Gas, analytics map relationships between asset conditions and output; for Mining, fleet utilization and haulage efficiency; for Utilities, end-to-end visibility across distribution grids.</p>"}, {"icon": "", "judul": "Anomaly Detection & Workplace Safety Monitoring", "teks": "<p>Energy facilities operate under stringent safety standards; identifying abnormal site conditions quickly protects personnel and assets.</p><p>AI algorithms analyze operational data streams to flag parameters deviating from normal baselines. Complementing numeric analytics, Computer Vision transforms standard CCTV networks into intelligent monitoring sensors—detecting PPE compliance, personnel presence in restricted zones, visual equipment anomalies, and environmental hazards. System alerts notify operators instantly, while action protocols remain controlled by qualified site personnel.</p>"}, {"icon": "", "judul": "Industrial Visual Inspection", "teks": "<p>Manual equipment inspections can be limited by human fatigue, accessibility, and coverage constraints.</p><p>Computer Vision automates visual analysis over video and imagery feeds to detect structural and mechanical anomalies across machinery, pipelines, and site facilities. AI models perform first-level visual screenings, allowing engineers to focus their attention on high-risk equipment conditions.</p>"}, {"icon": "", "judul": "IoT Data Platform & Real-Time Analytics", "teks": "<p>Industrial IoT (IIoT) facilitates large-scale sensor deployments across energy sites. However, raw sensor feeds require specialized data platforms capable of high-throughput ingestion, processing, and storage.</p><p>Sapta Tunas Teknologi builds data architectures that consolidate telemetry into modern Data Platforms or Data Lakehouses. Centralized data feeds real-time operational dashboards, historical trend analysis, and predictive AI models—enabling rapid incident response across sites.</p>"}, {"icon": "", "judul": "Satellite Intelligence & Environmental Monitoring", "teks": "<p>For operators managing expansive geographic concessions, ground-level site inspections can be slow and resource-intensive. Satellite imagery provides a continuous macro-perspective over vast operating territories.</p><p>Utilizing AI algorithms, satellite data is processed to track environmental and structural surface changes over time: for Mining, land clearing, excavation progression, and tailing pond boundaries; for Oil & Gas, pipeline right-of-way corridors and remote well pads; for Utilities, visibility across distributed transmission lines and field assets.</p>"}, {"icon": "", "judul": "Environmental Analytics & Sustainability Governance", "teks": "<p>Modern energy enterprises require consolidated reporting covering resource utilization, environmental impact metrics, and sustainability key indicators.</p><p>Modern Data Platforms unify environmental data into structured governance dashboards. Combined with satellite intelligence, companies gain complete visibility over operational footprints and surrounding ecosystems. Analytics models support internal monitoring and regulatory ESG reporting, structured around industry compliance standards.</p>"}]',2),
((SELECT id FROM industri WHERE slug='energy'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Protecting Converged IT and Operational Technology Environments','<p>Cybersecurity within the energy sector must protect two interconnected realms: Information Technology (IT) enterprise networks and Operational Technology (OT/ICS) industrial environments. While IT security incidents typically result in data loss or application downtime, OT breaches directly impact physical equipment, industrial processes, and human safety.</p><p>Sapta Tunas Teknologi delivers comprehensive cybersecurity frameworks designed specifically for converged IT and industrial OT ecosystems, including Managed ICS/OT Security and specialized IoT/ICS Security Assessments.</p>','[{"icon": "", "judul": "OT / ICS Security", "teks": "<p>Industrial Control Systems (ICS) possess distinct operational characteristics compared to standard enterprise IT. While IT patch management can be executed routinely, applying updates or rebooting OT environments requires careful evaluation to avoid interrupting continuous industrial operations.</p><p>OT security architectures must protect systems without compromising industrial process stability, controller latency, or system availability.</p>"}, {"icon": "", "judul": "Industrial Network Protection & Segmentation", "teks": "<p>A fundamental tenet of OT cybersecurity is eliminating flat network topologies. If a single edge device is compromised, micro-segmentation prevents threat actors from moving laterally into safety systems or core controllers.</p><p>Network segmentation divides industrial networks into functional security zones. Firewalls, access controls, and deep packet inspection (DPI) monitor inter-zone traffic, restricting non-essential protocols and limiting the blast radius of potential security incidents.</p>"}, {"icon": "", "judul": "Unified Threat Detection across IT & OT", "teks": "<p>Effective cybersecurity requires comprehensive visibility across corporate and plant networks. Security logs from endpoints, firewalls, network appliances, and industrial controllers aggregate into centralized SIEM/SOC platforms.</p><p>Enterprise monitoring tracks endpoints, identity platforms, and servers, while OT monitoring captures relevant industrial events without introducing network latency. Sapta Tunas Teknologi delivers Managed SOC, Managed SIEM, Incident Response, MDR (Managed Detection & Response), Threat Intelligence, and dedicated Managed ICS/OT services.</p>"}, {"icon": "", "judul": "Vulnerability Management & Security Posture Assessments", "teks": "<p>Cyber risks stem not only from external threat actors but also from unpatched systems, misconfigured industrial assets, and weak access policies.</p><p>We perform tailored security assessments across operational layers—Vulnerability Assessment & Penetration Testing (VAPT), Security Posture Assessment, Configuration & Policy Assessment, IoT/ICS Security Assessment, Compromise Assessment, and Red Teaming. Remediation plans for OT environments account for physical operational constraints, prioritizing controls that preserve industrial process integrity.</p>"}, {"icon": "", "judul": "Incident Response & Cyber Resiliency", "teks": "<p>Organizations must prepare for active breach scenarios alongside preventative measures.</p><p>Sapta Tunas Teknologi provides Incident Response & Recovery alongside Digital Forensics capabilities integrated into our Managed SOC services. Incident Response teams contain threats and restore affected systems, while Digital Forensics identifies root causes, entry vectors, and breach scopes. Combined with immutable backups, cyber recovery environments, and disaster recovery plans, energy firms establish a robust operational defense model.</p>"}]',3),
((SELECT id FROM industri WHERE slug='energy'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'Managed Services for Stable, Secure Remote Energy Operations','<p>Maintain control over energy operations in remote locations—such as mine sites, refineries, offshore platforms, generation plants, and substations—with 24/7 Managed Services built for harsh operational environments.</p><p>We supply responsive, remote IT support alongside proactive monitoring for field IT systems, operational networks, edge connectivity equipment, and site digital platforms. Continuous surveillance detects technical issues early, preventing unplanned operational disruptions.</p><p>Our services include advanced security components such as Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, and Table Top Exercises to protect critical national infrastructure (CNI).</p><p>We also assist in managing compliance against regulatory frameworks and industrial infrastructure cybersecurity guidelines, ensuring structured operational governance across all remote assets.</p>','[{"icon": "", "judul": "24/7 Remote IT Support", "teks": ""}, {"icon": "", "judul": "Field & Edge Monitoring", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}, {"icon": "", "judul": "CNI Compliance Management", "teks": ""}]',4),
((SELECT id FROM industri WHERE slug='cross-industry'),(SELECT id FROM solusi_pilar WHERE slug='modernize-infrastructure'),'Flexible & Adaptive Infrastructure','<p>Modern digital transformation challenges are no longer confined to specific vertical markets. Organizations across financial services, manufacturing, healthcare, retail, distribution, education, telecommunications, and the public sector face similar technology demands.</p><p>Sapta Tunas Teknologi builds an integrated digital foundation that drives business agility, operational efficiency, data-driven governance, and continuous security resilience.</p>','[{"icon": "", "judul": "Flexible & Adaptive Infrastructure", "teks": "<p>Business expansion introduces more applications, active users, and data traffic. Static infrastructure can become a bottleneck when workloads spike or when organizations adopt resource-intensive analytics and AI tools.</p><p>Sapta Tunas Teknologi builds scalable infrastructure architectures incorporating compute, enterprise storage, virtualization, networking, and flexible Hyperconverged (HCI) or Non-Hyperconverged configurations. Resource capacity scales modularly alongside workload growth, avoiding costly infrastructure overhauls.</p>"}, {"icon": "", "judul": "Multi-Cloud & Hybrid Cloud", "teks": "<p>Not all enterprise workloads belong on a single platform. Critical core databases often require the predictable performance and control of private infrastructure, whereas web applications benefit from public cloud elasticity.</p><p>Sapta Tunas Teknologi designs Hybrid Cloud Architectures that integrate on-premise data centers, private clouds, and public cloud platforms based on performance, security, compliance, data residency, and operational cost parameters—delivering multi-cloud agility while keeping application data governed and secure.</p>"}, {"icon": "", "judul": "Modern Workplace & Collaboration", "teks": "<p>Modern work environments require seamless productivity platforms accessible from headquarters, branch offices, client sites, or remote locations.</p><p>Our Modern Workplace solutions integrate users, endpoint devices, productivity applications, and collaboration platforms into a single digital working environment—encompassing document management, unified communications, endpoint management, and secure remote access while enforcing security controls over corporate data.</p>"}, {"icon": "", "judul": "Business Continuity & Data Protection", "teks": "<p>Hardware failures, human errors, ransomware attacks, software corruptions, or natural disasters can disrupt critical digital services at any time.</p><p>Sapta Tunas Teknologi designs end-to-end Business Continuity, Backup, Data Protection, Disaster Recovery, and Cyber Resiliency strategies. Applications are categorized by business criticality, defining clear Recovery Time Objectives (RTO) and Recovery Point Objectives (RPO).</p>"}, {"icon": "", "judul": "Cost Optimization & Infrastructure Efficiency", "teks": "<p>Modernizing IT infrastructure focuses on maximizing existing asset utilization. Virtualization, system consolidation, HCI architectures, workload placement, and capacity planning reduce infrastructure sprawl and lower operational overhead.</p><p>Resource monitoring provides visibility into CPU, memory, storage, and network utilization trends—ensuring expansion investments are driven by real usage data. We provide Aggregated & Disaggregated Solutions to balance performance, high availability, scalability, and cost efficiency.</p>"}]',1),
((SELECT id FROM industri WHERE slug='cross-industry'),(SELECT id FROM solusi_pilar WHERE slug='data-ai'),'Data & AI for Business Agility and Insight','<p>Artificial Intelligence is increasingly adopted to automate workflows and drive productivity, while leadership teams require fast access to reliable operational metrics.</p><p>Sapta Tunas Teknologi focuses on deploying Data & AI where it delivers clear, measurable business value—spanning Agentic AI, Computer Vision, AI Platforms, Data Management tools, and Data Lakehouses.</p>','[{"icon": "", "judul": "Business Intelligence & Advanced Analytics", "teks": "<p>Business Intelligence consolidates data from ERPs, CRMs, financial systems, and operational software into executive dashboards.</p><p>Advanced Analytics takes this further by answering complex operational questions—covering sales analytics, financial performance tracking, supply chain visibility, inventory management, and executive reporting.</p>"}, {"icon": "", "judul": "AI/ML for Automation & Insight", "teks": "<p>Artificial Intelligence and Machine Learning automate manual data processing through classification, recommendation engines, anomaly detection, data extraction, and predictive models.</p><p>Generative AI enables employees to query knowledge bases, summarize long documents, and extract contextual insights efficiently. Agentic AI executes multi-step operational workflows based on predefined business rules and permission boundaries.</p>"}, {"icon": "", "judul": "Customer Experience Analytics", "teks": "<p>Customer Analytics consolidates interaction data across sales teams, support desks, transaction portals, and loyalty programs to build unified customer profiles.</p><p>Organisations can segment customer bases, track behavioral trends, evaluate channel performance, and measure marketing campaign efficacy. AI layers provide automated product recommendations and behavioral insights while respecting data privacy principles.</p>"}, {"icon": "", "judul": "Data Governance & Quality", "teks": "<p>AI tools depend on accurate underlying data. Duplicate records, inconsistent formatting, or unassigned data ownership degrade analytics accuracy.</p><p>Data Governance establishes clear ownership, classification standards, access policies, and data lifecycles. Data Quality management enforces completeness, consistency, and accuracy across systems—critical when implementing Generative AI so that access controls reflect underlying data source permissions.</p>"}, {"icon": "", "judul": "Enterprise Data Platform", "teks": "<p>Data silos scatter information across disparate databases, applications, and cloud services.</p><p>Sapta Tunas Teknologi constructs modern Enterprise Data Platforms that consolidate structured and unstructured data into an integrated Data Lakehouse foundation—a central hub connecting source systems with Business Intelligence, Advanced Analytics, Machine Learning models, and enterprise applications.</p>"}]',2),
((SELECT id FROM industri WHERE slug='cross-industry'),(SELECT id FROM solusi_pilar WHERE slug='cybersecurity'),'Continuous Security Resilience for the Modern Enterprise','<p>Expanding cloud adoption broadens enterprise attack surfaces. Cloud platforms, mobile devices, SaaS, and remote work have dissolved traditional network perimeters.</p><p>Sapta Tunas Teknologi delivers a layered cybersecurity approach that verifies identity and context, monitors continuously, and aligns governance with regulatory standards.</p>','[{"icon": "", "judul": "Zero Trust Security", "teks": "<p>Traditional perimeter security assumed inside network traffic was inherently trustworthy. Cloud adoption, mobile devices, SaaS platforms, and remote work have dissolved traditional network perimeters.</p><p>Identity and Access Management (IAM), endpoint security, micro-segmentation, and continuous monitoring work together to verify identity, device health, and context before granting application access.</p>"}, {"icon": "", "judul": "Managed Security Services", "teks": "<p>Building an in-house, 24/7 Security Operations Center (SOC) demands substantial capital investments in technology and specialized talent.</p><p>Managed Security Services provide a scalable alternative. Sapta Tunas Teknologi delivers centralized security monitoring through SOC as a Service, Managed SIEM, Managed Detection & Response (MDR), Threat Intelligence, and Incident Response—with analysts detecting, investigating, and remediating suspicious activity around the clock.</p>"}, {"icon": "", "judul": "Email & Data Protection", "teks": "<p>Email remains a primary enterprise communication channel and a common entry vector for cyber threats—including phishing, malicious attachments, and credential harvesting.</p><p>Email protection must be combined with identity security, endpoint defense, and encryption across all data states: at rest, in motion, and in use.</p>"}, {"icon": "", "judul": "Cloud Security Posture Management (CSPM)", "teks": "<p>Misconfigured cloud storage buckets, overly permissive IAM roles, exposed management ports, and inconsistent security policies increase corporate risk exposure across public cloud environments.</p><p>Cloud Security Posture Management (CSPM) delivers continuous visibility across multi-cloud infrastructure, detecting misconfigurations and policy drift early—enabling security teams to remediate issues before exploitation occurs.</p>"}, {"icon": "", "judul": "Security Awareness & Regulatory Compliance", "teks": "<p>Security Awareness programs educate employees on phishing recognition, credential protection, and safe data handling practices.</p><p>Our Cybersecurity Services portfolio offers Security Risk Compliance, Forensic Readiness, ISO 27001 Consulting, Personal Data Protection (PDP/UU PDP) alignment, Vulnerability Assessments, and Security Posture Reviews to ensure governance frameworks align with regulatory standards.</p>"}]',3),
((SELECT id FROM industri WHERE slug='cross-industry'),(SELECT id FROM solusi_pilar WHERE slug='managed-services'),'End-to-End Managed Services for Cross-Industry Digital Ecosystems','<p>Whether managing university campus networks, smart commercial buildings, or logistics distribution hubs, unexpected IT outages directly impair daily operations and service delivery. Our Managed Services support organizations across education, real estate, transportation, and logistics in maintaining stable, secure, and available digital infrastructure.</p><p>We deliver end-to-end management spanning distributed IT environments—including campus Wi-Fi networks, learning management servers, Smart Building IoT devices, CCTV networks, access control systems, building management platforms, and distribution node connectivity. Proactive 24/7/365 monitoring identifies and resolves potential network issues before operations are impacted.</p><p>Advanced security services—including Vulnerability Assessment & Penetration Testing (VAPT), Digital Forensics, Cyber Drills, and Table Top Exercises—strengthen system defenses against evolving cyber threats, protecting sensitive records and mission-critical operational tools.</p><p>Through integrated Managed Services, cross-industry enterprises can maintain network stability, accelerate technical support response times, reduce internal IT burdens, and secure confidential data across their entire operating footprint.</p>','[{"icon": "", "judul": "24/7/365 Monitoring", "teks": ""}, {"icon": "", "judul": "Campus & Smart Building IoT", "teks": ""}, {"icon": "", "judul": "CCTV & Access Control", "teks": ""}, {"icon": "", "judul": "VAPT", "teks": ""}, {"icon": "", "judul": "Digital Forensics", "teks": ""}, {"icon": "", "judul": "Cyber Drills", "teks": ""}, {"icon": "", "judul": "Table Top Exercises", "teks": ""}]',4);
