-- ============================================================
-- Migration: Industry detail content — ENGLISH (default language)
-- Source: client Industry_Solutions_Eng.docx (7 industries x 4 pillars).
-- Replaces base-column content for industri + industri_pilar, and
-- renames pillar 1 to 'IT Infrastructure'. Matched by slug (id-safe).
-- Default language is English, so base columns hold the English text.
-- In phpMyAdmin: select your DB, open SQL, paste this, Go.
-- ============================================================

SET NAMES utf8mb4;

-- 1) Pillar labels (shown as the per-pillar eyebrow). Match the docx.
UPDATE `solusi_pilar` SET `nama`='IT Infrastructure' WHERE `slug`='modernize-infrastructure';
UPDATE `solusi_pilar` SET `nama`='Data & AI' WHERE `slug`='data-ai';
UPDATE `solusi_pilar` SET `nama`='Cybersecurity' WHERE `slug`='cybersecurity';
UPDATE `solusi_pilar` SET `nama`='Managed Services' WHERE `slug`='managed-services';

-- 2) Industry label + hero intro (English).
UPDATE `industri` SET `label`='Financial Services & E-Commerce', `judul`='Financial Services <b>& E-Commerce</b>', `intro`='Secure, always-on digital foundations — infrastructure, data, AI, and cybersecurity — built for financial services and e-commerce at scale.' WHERE `slug`='financial';
UPDATE `industri` SET `label`='Manufacture & FMCG', `judul`='Manufacture <b>& FMCG</b>', `intro`='Modern IT for manufacturing and FMCG — edge computing, computer vision, and IT/OT security that keep production fast, safe, and always running.' WHERE `slug`='manufacture';
UPDATE `industri` SET `label`='Healthcare', `judul`='<b>Healthcare</b>', `intro`='Reliable, secure healthcare technology — from medical data infrastructure and clinical AI to protection for patient data and connected medical devices.' WHERE `slug`='healthcare';
UPDATE `industri` SET `label`='Telecommunications (ICT)', `judul`='Telecommunications <b>(ICT)</b>', `intro`='Hyperscale, software-defined infrastructure with GenAI customer service and carrier-grade security — built for 4G/5G and ICT ecosystems.' WHERE `slug`='telecom';
UPDATE `industri` SET `label`='Law Enforcement', `judul`='Law <b>Enforcement</b>', `intro`='A secure, connected, and intelligent technology foundation for law enforcement — integrating IT infrastructure, data & AI, and cybersecurity for mission-critical operations.' WHERE `slug`='law-enforcement';
UPDATE `industri` SET `label`='Energy', `judul`='<b>Energy</b>', `intro`='Resilient, intelligent, and secure technology for oil, gas, mining, and utilities — spanning rugged infrastructure, operational data & AI, and converged IT/OT security.' WHERE `slug`='energy';
UPDATE `industri` SET `label`='Cross Industry', `judul`='Cross <b>Industry</b>', `intro`='Flexible, intelligent, and secure digital foundations — scalable infrastructure, data & AI, and continuous security resilience — for organizations across every sector.' WHERE `slug`='cross-industry';

